css:
.switch-container {
  position: relative;
}
.switch-container input {
  display: none;
}
.switch {
  position: relative;
  width: 120px;
  height: 50px;
  border-radius: 25px;
  background: #ddd;
  display: flex;
  align-items: center;
  padding: 5px;
  cursor: pointer;
  transition:
    background 0.4s cubic-bezier(0.4, 0, 0.2, 1),
    box-shadow 0.3s ease;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
}
.switch .toggle {
  position: absolute;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: white;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.3);
  display: flex;
  justify-content: center;
  align-items: center;
  transition:
    transform 0.4s cubic-bezier(0.4, 0, 0.2, 1),
    background 0.3s ease;
}
.switch svg {
  width: 24px;
  height: 24px;
  fill: black;
  opacity: 0.5;
  transition:
    transform 0.4s cubic-bezier(0.4, 0, 0.2, 1),
    opacity 0.3s ease;
}
.switch-container input:checked + .switch {
  background: #f9a825;
}
.switch-container input:checked + .switch .toggle {
  transform: translateX(65px);
  background: #fff3e0;
}
.switch-container input:checked + .switch svg {
  transform: rotate(180deg);
  opacity: 0.7;
}
